settings.custom_css:
selector {
  position: relative;
}

selector .lmn-slider-dots {
  position: absolute;
  top: 50%;
  left: 30px;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  gap: 14px;
  z-index: 10;
}

selector .lmn-slider-dots .dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background-color: #FBF7F3;
  opacity: 0.45;
  transition: all 0.3s ease;
}

selector .lmn-slider-dots .dot.active {
  width: 18px;
  height: 18px;
  opacity: 1;
}

selector {
  background-color: transparent !important;
  transition: background-color 0.4s ease;
}

selector .elementor-widget {
  opacity: 0;
  transition: opacity 0.4s ease;
}

selector:hover {
  background-color: rgba(31, 30, 30, 0.82) !important; /* שקול ל-#1F1E1ED1 */
}

selector:hover .elementor-widget {
  opacity: 1;
}
